/* RAVN South interactive site prototype. Data remains in the visitor's browser. */
const A='https://ravn-south-testing.decentstoat4.chatgpt.site/assets/';
const $=(s)=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'',training:'',nutrition:'',mentality:'',vault:'',arena:'',dashboard:''};
const nav=[['/','Home'],['/fitness-programmes','Fitness Programmes'],['/nutrition','Nutrition'],['/mentality','Mentality'],['/vault','RAVN Vault'],['/arena','RAVN Arena'],['/coaches','Coaches'],['/dashboard','Dashboard']];
const defaults={name:'RAVN Member',joined:false,tier:'Free',points:0,logs:[],program:'Foundation Strength',posts:[],likes:[],groups:[],messages:[],nutrition:[],stories:[],gifts:[],buddies:[],searchTerm:'',checkinText:'',goals:[],visibility:'members',email:'',notices:true};
let s={...defaults,...JSON.parse(localStorage.getItem('ravn-demo-v2')||'{}')};
function save(){localStorage.setItem('ravn-demo-v2',JSON.stringify(s))}
// Remove retired bonus records once; keep all genuine action history and points.
{ const retired=s.logs.filter(log=>log.key==='first-accolade');
  if(retired.length){s.points=Math.max(0,s.points-retired.reduce((total,log)=>total+(Number(log.points)||0),0));s.logs=s.logs.filter(log=>log.key!=='first-accolade');save();}
}

function path(){return decodeURI(location.hash.slice(1)||'/').split('?')[0].replace(/\/$/,'')||'/'}
function navto(p){location.hash='#'+p}
function toast(msg){let old=$('.toast');if(old)old.remove();let d=document.createElement('div');d.className='toast';d.textContent=msg;document.body.appendChild(d);setTimeout(()=>d.remove(),2900)}
const today=()=>new Date().toISOString().slice(0,10);
const month=()=>new Date().toISOString().slice(0,7);
function logAction(key,points,label,scope='day'){
 if(!s.joined){toast('Enter member demo first to track achievements.');navto('/login');return}
 let ref=scope==='day'?today():scope==='month'?month():'once';
 if(s.logs.some(x=>x.key===key&&x.ref===ref)){toast('Already recorded for this period — consistency counts.');return}
 s.logs.unshift({key,points,label,ref,date:new Date().toISOString()});s.points+=points;
 save();toast('+'+points+' points · '+label);render();
}
const logged=(key)=>s.logs.some(l=>l.key===key&&l.ref===today());
const logsMonth=()=>s.logs.filter(l=>l.date.slice(0,7)===month());
const monthly=()=>logsMonth().reduce((n,l)=>n+l.points,0);
const level=()=>Math.floor(s.points/500)+1;
const pct=()=>Math.min(100,Math.round((s.points%500)/5));
const avatar=n=>`<span class="avatar">${esc(n).split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase()}</span>`;
const btn=(href,label,outline=false)=>`<a class="${outline?'btn-outline':'btn'}" href="#${href}">${label}</a>`;
const pageHero=(title,sub,desc)=>`<section class="hero-custom"><div class="wrap"><div class="eyebrow">RAVN SOUTH · DO IT. PROVE IT.</div><h1>${title}</h1><div class="eyebrow" style="color:#e5c39b">${sub}</div><p class="lead">${desc}</p></div></section>`;
const section=(title,body,after='')=>`<section class="section"><div class="wrap"><div class="sectionhead"><h2>${title}</h2>${after}</div>${body}</div></section>`;
const card=(html,cls='')=>`<article class="card ${cls}">${html}</article>`;
const footlinks=[['/about','Our Story'],['/media','Media'],['/coaches','Meet the Coaches'],['/contact','Contact'],['/faq','FAQs'],['/privacy','Privacy'],['/terms','Terms'],['/disclaimer','Disclaimer']];
function header(){let p=path();return `<header class="topbar"><div class="topinner"><a class="brand" href="#/"><img class="brand-logo" src="${A}ravn-master-logo-tight-crisp.svg" alt="RAVN SOUTH"></a><nav class="nav" id="mainnav">${nav.map(([u,n])=>`<a class="${u===p||(u!=='/'&&p.startsWith(u+'/'))?'active':''}" href="#${u}">${n}</a>`).join('')}</nav><div class="topactions"><a class="btn-soft small account-link" href="#${s.joined?'/dashboard':'/login'}">${s.joined?'MY DASHBOARD':'MEMBER LOGIN'}</a><button type="button" class="btn-soft small menu-btn" data-action="menu" aria-label="Open navigation">☰</button></div></div></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-cols"><div><div class="brand"><img class="brand-logo" src="${A}ravn-master-logo-crisp.svg" alt="RAVN SOUTH — DO IT. PROVE IT."></div><p>Do it. Prove it.<br>Every step is an achievement.</p></div><div><h4>Explore</h4>${nav.slice(1,5).map(([p,n])=>`<a href="#${p}">${n}</a>`).join('')}</div><div><h4>Members</h4>${[['/dashboard','Dashboard'],['/profile','Profile'],['/settings','Settings'],['/goals','Goals']].map(([p,n])=>`<a href="#${p}">${n}</a>`).join('')}</div><div><h4>Information</h4>${footlinks.map(([p,n])=>`<a href="#${p}">${n}</a>`).join('')}</div></div><div class="foot-bottom">© ${new Date().getFullYear()} RAVN South · Interactive development prototype · Demo progress stored only in this browser. No live accounts or payments. Profile snapshots are shared only when you choose. <a href="#/disclaimer">Site disclaimer</a>.</div></div></footer>`}
function memberNotice(){return !s.joined?`<div class="notice">This is a working prototype. <a href="#/login" style="text-decoration:underline">Enter the member demo</a> to try progress tracking. Your changes are saved on this device only.</div>`:''}
function progressCard(){return card(`<div class="eyebrow">YOUR PROGRESSION</div><h3>${esc(s.name)}</h3><div class="stats" style="grid-template-columns:repeat(2,1fr)"><div class="stat"><strong>${s.points}</strong><span>Total points</span></div><div class="stat"><strong>${level()}</strong><span>Level</span></div></div><div class="progress" style="margin-top:22px"><span style="width:${pct()}%"></span></div><small>${s.points%500} / 500 points to next level</small><div class="line"></div>${btn('/dashboard','View dashboard')}`)}
const mentalityElements=['FIRE','ICE','EARTH','WATER','LIGHTNING'];
function stepArt(i){const scenes=['Motivation: a flame sparks into life, representing the reason to begin','Determination: steadfast earth breaks through ice, representing persistence through difficulty','Gratification: strong roots and living earth represent the growth earned through effort','Sustainability: water flows around stones, representing adaptable balanced habits','Maintenance: lightning represents renewed energy and staying alert to protect progress'];return `<span class="step-photo"><img src="${A}mentality-element-${i===2?'earth':pillars[i][0].toLowerCase()}.png" alt="${scenes[i]}" loading="lazy"></span>`}

function home(){return `<section class="hero-crop hero-short clickable-hero"><img src="${A}home-hero.webp" alt="RAVN South original website hero with Jack and Jill against a mountain landscape"></section><div class="home-hero-actions"><a class="btn home-start-button" href="#/signup" aria-label="Start your RAVN South journey">START YOUR JOURNEY →</a></div><div class="wrap" style="padding-top:14px"><div class="eyebrow center">STRENGTH · ENDURANCE · VITALITY · MENTALITY · LONGEVITY</div></div>${section('BUILD YOUR JOURNEY',`<div class="grid cols3">${[['training','TRAINING','Build strength. Build endurance. Build you.','/fitness-programmes'],['nutrition','NUTRITION','Real food. Real energy. Real results.','/nutrition'],['mentality','MENTALITY','A strong mind builds a stronger life.','/mentality']].map(([im,t,sub,p])=>`<a class="image-tile journey-tile ${im==='nutrition'?'nutrition-hd-tile':''}" href="#${p}" aria-label="Explore ${t.toLowerCase()}"><img src="${A+(im==='training'?'training-seated-hood':im==='nutrition'?'nutrition-hd':im)}.webp" alt="${t}: ${sub}">${im==='nutrition'?`<div class="nutrition-tile-copy"><svg viewBox="0 0 48 56" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round"><path d="M8 3v14c0 8 12 8 12 0V3M14 3v48M35 3c-10 0-10 25 0 25s10-25 0-25Zm0 25v23"/></g></svg><h3>NUTRITION</h3><p>REAL FOOD. REAL ENERGY.<br>REAL RESULTS.</p><span>VIEW PLANS →</span></div>`:''}</a>`).join('')}</div>`)}${section('MORE THAN A FITNESS PROGRAMME',`<div class="grid cols3 community-design-grid">${[['vault','RAVN VAULT','Share your journey. Celebrate progress.','Enter Vault',20],['arena','RAVN ARENA','Earn your place. Prove your progress.','Explore Arena',525],['dashboard','YOUR DASHBOARD','Your goals. Your plans. Your progress.','My Dashboard',1027]].map(([path,title,copy,cta,x])=>`<a class="community-design-card" href="#/${path}" aria-label="${title}: ${copy} ${cta}" style="--art-left:${-x/490*100}%"><img src="${A}community-cards-branded.png" alt="" aria-hidden="true" loading="lazy" width="1536" height="1024"><span class="visually-hidden">${title} — ${copy} ${cta} →</span></a>`).join('')}</div>`)}<section class="section"><div class="wrap"><div class="callout"><div><div class="eyebrow">THE FIRST STEP COUNTS</div><h2>DO IT. PROVE IT.</h2><p>Progress starts with turning up, not being perfect.</p></div>${btn('/signup','Start your journey →')}</div></div></section>`}
const programData=[{slug:'form-control',title:'Form & Control',tag:'Week 1 · Begin with confidence',desc:'Controlled movements, technique and a manageable routine.',ex:['Warm-up and mobility','Squat pattern · 3 × 10','Incline pressing · 3 × 10','Seated row · 3 × 10','Cool down and reflect']},{slug:'foundation',title:'Foundation',tag:'Week 2 · Build your base',desc:'Build dependable habits and develop strength safely.',ex:['Movement preparation','Leg press · 3 × 10','Incline dumbbell press · 3 × 10','Cable row · 3 × 10','Light cardio finish']},{slug:'muscle-building',title:'Muscle Building',tag:'Week 3 · Progressive effort',desc:'Introduce manageable progressive overload while protecting technique.',ex:['Warm up','Incline bench · 3 × 8–10','Lat pulldown · 3 × 8–10','Leg extension · 3 × 10','Reflect and record effort']},{slug:'lactic-capacity',title:'Lactic Capacity',tag:'Week 6 · Keep moving forward',desc:'A more demanding phase unlocked as your consistency grows.',ex:['Longer warm-up','Alternating resistance circuits','Conditioning intervals','Mobility and recovery','Progress reflection']}];
function training(){return pageHero('TRAINING','BUILD STRENGTH. BUILD ENDURANCE. BUILD YOU.','Structured training that meets you where you are. Earn points for following through, not chasing someone else’s numbers.')+section('YOUR TRAINING PATH',`<div class="grid cols4">${programData.map((x,i)=>card(`<div class="eyebrow">${x.tag}</div><h3>${x.title}</h3><div class="eyebrow">${legacyTrainingLevel(x.slug)}</div>${accessLabel(legacyTrainingLevel(x.slug))}<p>${x.desc}</p>${btn('/training/'+x.slug,'View programme',true)}`)).join('')}</div>`)+section('STRETCHING',card('<h3>MOVE FREELY. BUILD YOUR ROUTINE.</h3><p>Beginner stretching is free. Explore Intermediate and Advanced routines with Subscription.</p>'+btn('/fitness-programmes/category/stretching','Explore stretching',true)))+section('RECORD YOUR TRAINING',`<div class="grid cols2">${card(`<h3>Today’s training</h3><p>Completing a planned session earns 10 points, once a day.</p><button class="btn" data-action="log" data-key="training" data-points="10" data-label="Planned training completed" ${logged('training')?'disabled':''}>${logged('training')?'✓ Session recorded':'Complete training · +10 pts'}</button><div class="line"></div><p class="mini">A demo check-in: it does not verify physical activity.</p>`)}${progressCard()}</div>`)}
function trainingDetail(slug){const pr=programData.find(x=>x.slug===slug);if(!pr)return notFound();if(!programmeAllowed(legacyTrainingLevel(slug)))return pageHero(pr.title.toUpperCase(),legacyTrainingLevel(slug),pr.desc)+section('PROGRAMME ACCESS',programmeLock(legacyTrainingLevel(slug)));return pageHero(pr.title.toUpperCase(),'YOUR TRAINING PROGRAMME',pr.desc)+section('PROGRAMME OVERVIEW',`<div class="grid cols2">${card(`<div class="eyebrow">${pr.tag}</div><h3>Suggested session</h3><div class="list">${pr.ex.map((x,i)=>`<div class="list-row"><span><span style="color:var(--gold)">0${i+1}</span> &nbsp;${x}</span><span class="muted">✓</span></div>`).join('')}</div><div class="line"></div><button class="btn" data-action="choose-program" data-program="${esc(pr.title)}">Use this programme</button>`)}${card(`<h3>YOUR PROGRESS</h3><p>Selected programme: <strong>${esc(s.program)}</strong></p><p>Training recorded today: <strong>${logged('training')?'Yes':'Not yet'}</strong></p><button class="btn-outline" data-action="log" data-key="training" data-points="10" data-label="Planned training completed" ${logged('training')?'disabled':''}>${logged('training')?'Already completed':'Mark session complete · +10 pts'}</button><div class="line"></div><small>Programme content is illustrative and should be tailored to the individual. Progress gradually at your own ability.</small></div>`)} </div>`)+section('GET GUIDANCE',card(`<h3>Questions about technique?</h3><p>Talk through training concepts with Coach Jack in the interactive demo.</p>${btn('/coach/jack','Ask Coach Jack')}`))}
function nutrition(){return RavnNutrition.hub()}
function rotation(){return RavnNutrition.rotation()}
function nutritionDetail(diet,goal,variation){return RavnNutrition.plan(diet,goal,variation)}
function nutritionSnacks(){return RavnNutrition.snacks()}
function nutritionShopping(){return RavnNutrition.shopping()}
const pillars=[['MOTIVATION','The spark that starts it.','Find the reason that matters to you. It might be feeling more confident, having energy for your family, improving your health or enjoying movement again. Understanding your own reason gives you something to return to when enthusiasm drops. Start with one small action that brings you closer to it.','pillar-motivation'],['DETERMINATION','The grit that keeps you.','Turn your reason into regular action. Determination means keeping manageable promises to yourself, even when the initial excitement fades. Plan what you can realistically do, check in with your progress and learn from difficult days. A missed session is a chance to reset and carry on, rather than give up.','pillar-determination'],['GRATIFICATION','The reward that drives you.','Notice and celebrate what you have achieved, from your first consistent week to feeling stronger or more confident. Enjoy those wins, but watch for the temptation to stop once you see early results. Use each achievement as encouragement to keep going, and choose your next small step.','pillar-gratification'],['SUSTAINABILITY','The balance that lasts.','Build a routine that fits your real life. Training, food choices and personal goals should support your health without overwhelming your family, work or relationships. Choose habits you can afford in time, energy and money. Adjust the plan when life changes so progress remains manageable over the long term.','pillar-sustainability'],['MAINTENANCE','The habits that protect you.','Protect the progress you have worked for. Once you reach a goal, keep the everyday habits that helped you get there: regular movement, balanced meals, rest and honest check-ins. Notice when old patterns return and make small adjustments early. Maintenance means continuing to care for yourself as your needs change.','pillar-maintenance']];
const stepJourneyCopy=['Every journey begins with a spark. Find the reason that makes you want to move.','Keep going when the path gets difficult. Build trust in the promises you make to yourself.','Pause in the light of what you have achieved. Enjoy the view, then keep your journey moving.','Find your flow. Let your routine adapt around family, work and the life you want to live.','Put down roots. Keep caring for the habits that protect how far you have come.'];
function elementStepLinks(){return `<div class="element-emblems">${pillars.map(([n,t],i)=>`<a class="element-emblem" href="#/mentality/${n.toLowerCase()}"><span class="element-orb"><img src="${A}mentality-element-${i===4?'lightning':i===2?'earth':n.toLowerCase()}.png" alt="${mentalityElements[i].toLowerCase()}" loading="lazy"></span><span class="eyebrow">STEP 0${i+1} · ${mentalityElements[i]}</span><h3>${n}</h3><p>${t}</p><span class="step-explore">Explore this step →</span></a>`).join('')}</div>`}
function mentality(){return pageHero('FIVE-STEP PROGRAM TO MENTALITY','ONE JOURNEY. FIVE STEPS.','From finding your reason to protecting your progress. Take the journey with Jack and Jill, one step at a time.')+`<section class="mentality-journey-intro"><div class="wrap mentality-journey-pair"><div class="mentality-journey-copy"><div class="eyebrow">FACE THE JOURNEY TOGETHER</div><h2>YOUR NEXT STEP STARTS HERE.</h2><p>Motivation starts the journey. Determination keeps you moving. Gratification celebrates how far you have come. Sustainability makes it part of your life. Maintenance keeps it alive.</p><p>Choose a step below to explore Jack and Jill’s journey through the mountains, picnic, boat trip and coastal bike ride.</p></div></div></section>`+section('EXPLORE THE FIVE STEPS',elementStepLinks())+section('YOUR MENTALITY JOURNEY',`<div class="grid cols2"><a class="approved-coach-card approved-coach-jill" href="#/coach/jill" aria-label="Talk to Coach Jill — mentality and mindset"><img src="${A}coaches-sunrise-approved.png" alt="Coach Jill with the agreed sunrise, mountains and lake background"><span class="visually-hidden">Talk to Coach Jill</span></a>${card(`<h3>Understand your own reasons</h3><p>Coach Jill can help you reflect on motivation, obstacles, consistency and your five-step program to mentality.</p>${btn('/coach/jill','Talk with Coach Jill')}`)}</div>`)}

function pillarDetail(slug){let p=pillars.find(x=>x[0].toLowerCase()===slug);if(!p)return notFound();const i=pillars.indexOf(p);const descriptions=['Jack and Jill preparing to start their journey at a lakeside jetty at dawn','Jack and Jill continuing up a mountain trail together','Jack and Jill celebrating their progress with a healthy picnic beside a waterfall','Jack and Jill making time for balance on a boat trip through a fjord','Jack and Jill keeping an enjoyable cycling routine along the coast'];return pageHero('STEP 0'+(i+1)+' · '+p[0],p[1].toUpperCase(),'')+`<section class="step-story-scene"><img src="${A}pillar-scene-${slug==='sustainability'?'sustainability-corrected':slug}.webp" alt="${descriptions[i]}"><div class="step-story-caption"><div class="eyebrow">JACK & JILL’S JOURNEY · STEP 0${i+1}</div><p>${stepJourneyCopy[i]}</p></div></section>`+section('PUT IT INTO PRACTICE',`<div class="grid cols2">${card(`<h3>${p[0]} IN ACTION</h3><p>${p[2]}</p><p>What would one small action in this area look like today?</p><a class="btn-outline" href="#/mentality">All five steps</a>`)}${card(`<h3>YOUR REFLECTION</h3><label class="field"><span>What is one step you can take?</span><textarea id="reflect" rows="5" placeholder="Write your next step..."></textarea></label><button class="btn" data-action="reflect" data-pillar="${p[0]}">Save reflection</button><p class="mini">Saved privately in this demo browser.</p>`)}</div><nav class="step-story-navigation" aria-label="Move through the five-step journey">${i>0?btn('/mentality/'+pillars[i-1][0].toLowerCase(),'← '+pillars[i-1][0],true):btn('/mentality','← All five steps',true)}${i<4?btn('/mentality/'+pillars[i+1][0].toLowerCase(),pillars[i+1][0]+' →'):btn('/coach/jill','Continue with Jill →')}</nav>`) }

function vault(){return `<section class="hero-crop clickable-hero"><img src="${A}vault-hero.webp" alt="RAVN Vault original hero design"><a class="hero-hotspot vault-hotspot" href="#/vault/feed" aria-label="Join RAVN Vault community"></a></section>${section('CONNECT · SHARE · GROW',`<div class="grid cols5">${[['','Profiles','/profile'],['','Messaging','/messages'],['','Groups','/groups'],['','Stories & Posts','/vault/feed'],['','Gifting','/vault/gifting']].map(([ic,n,p])=>card(`<h3>${n}</h3>${btn(p,'Explore',true)}`)).join('')}</div>`)}${section('LATEST FROM THE VAULT',feedInner(),btn('/vault/feed','See full community feed',true))}${section('MORE WAYS TO CONNECT',`<div class="grid cols3">${[['','MEMBER STORIES','/vault/stories','Short updates from everyday journeys.'],['','GIFTING','/vault/gifting','Recognise and encourage another member.'],['','TRAINING BUDDIES','/vault/buddies','Connect around shared training goals.']].map(([ic,t,href,sub])=>card(`<h3>${t}</h3><p>${sub}</p>${btn(href,'Explore',true)}`)).join('')}</div>`)}`}
const samplePosts=[{id:'s1',name:'Hannah P.',text:'Small win: showed up for the gym even when I nearly turned around. That counts.',likes:24,age:'2 hours ago'},{id:'s2',name:'Mark D.',text:'Meal prep finished for the week. Keeping things simple and sustainable.',likes:18,age:'4 hours ago'},{id:'s3',name:'Emma L.',text:'Feeling more confident with my training form this month.',likes:38,age:'Yesterday'}];
function feedInner(full=false){const postlist=[...s.posts,...samplePosts].slice(0,full?99:3);return `<div class="grid cols2"><div>${memberNotice()}${card(`<h3>SHARE YOUR JOURNEY</h3><label class="field"><span>Your update</span><textarea id="posttext" maxlength="800" rows="3" placeholder="Share a small win, question or update..."></textarea></label><button class="btn" data-action="post">Share post</button><p class="mini">Demo posts are visible only in your own browser.</p>`)}<div style="height:18px"></div>${postlist.map(p=>card(`<div class="post-header">${avatar(p.name)}<div><strong>${esc(p.name)}</strong><div class="mini">${p.age||'Just now'}</div></div></div><div class="post-body">${esc(p.text)}</div><div class="post-tools"><button data-action="like" data-id="${p.id}">${s.likes.includes(p.id)?'♥ Liked':'♡ Like'} · ${p.likes+(s.likes.includes(p.id)?1:0)}</button></div>`,'post')).join('')}</div><div>${card(`<h3>POPULAR TOPICS</h3><div class="list">${['Training & Workouts','Nutrition & Recipes','Mindset & Motivation','Progress & Achievements','General Chat','Challenges'].map(x=>`<div class="list-row"><a href="#/groups">${x}</a></div>`).join('')}</div>`)}<div style="height:18px"></div>${card(`<h3>IT’S NOT A RACE.</h3><div class="quote">IT’S YOUR JOURNEY.</div><p>Consistency. Effort. Real progress.</p>${btn('/groups','Find your tribe',true)}`)}</div></div>`}
function feed(){return pageHero('VAULT COMMUNITY','REAL PEOPLE. REAL PROGRESS. TOGETHER.','Celebrate wins, ask questions and support each other.')+section('COMMUNITY FEED',feedInner(true))}
const leaderboard=[['Sarah T.',1245,12,1],['Mark D.',1120,10,1],['Emma L.',980,9,0],['James K.',910,8,0],['Hannah P.',840,7,0]];
function rankRows(period='month'){let rows=[...leaderboard.map(x=>({name:x[0],points:x[1],badges:x[2],trophies:x[3]}))];if(s.joined)rows.push({name:s.name+' (you)',points:period==='month'?monthly():s.points,badges:arenaTrophyData().badges,trophies:arenaTrophyData().total,self:true});rows.sort((a,b)=>b.points-a.points);return rows.map((r,i)=>`<tr class="${r.self?'highlight':''}"><td>${i===0?'🥇':i===1?'🥈':i===2?'🥉':'#'+(i+1)}</td><td>${esc(r.name)}</td><td>${r.points.toLocaleString()}</td><td>${r.badges}</td><td>${r.trophies}</td></tr>`).join('')}
function arena(){
 const features=[['','POINTS','Daily actions and achievements'],['','BADGES','Bigger achievements'],['','TROPHIES','Major milestones'],['','RANKINGS','Climb the leaderboard']];
 const featureCards='<div class="grid cols4">'+features.map(x=>card('<h3>'+x[1]+'</h3><p>'+x[2]+'</p>')).join('')+'</div>';
 const panel=card('<div class="eyebrow">MEMBERS ONLY · MONTHLY COMPETITION</div><div class="tabs"><button class="tab active" data-action="leader-tab" data-period="month">This month</button><button class="tab" data-action="leader-tab" data-period="all">All time</button></div><div class="tablewrap"><table><thead><tr><th>Rank</th><th>Member</th><th>Points</th><th>Badges</th><th>Trophies</th></tr></thead><tbody id="leaderrows">'+rankRows()+'</tbody></table></div><p class="mini">Other member names and scores are illustrative, not genuine rankings.</p>');
 const scoring=card('<div class="eyebrow">HOW SCORING WORKS</div><h3>Accountability creates achievement</h3>'+[['Training session',10],['Nutrition target',10],['Accountability',5],['Monthly challenge',20]].map(x=>'<div class="list-row"><span>'+x[0]+'</span><strong style="color:var(--green)">+'+x[1]+' pts</strong></div>').join('')+'<div class="line"></div><h3>YOUR PROGRESS</h3><p>'+s.points+' points · Level '+level()+'</p>'+btn('/dashboard','My dashboard',true));
 const legacy='<div class="grid cols2">'+card('<h3>HALL OF FAME</h3><p>Permanent recognition for consistent achievers.</p>'+btn('/hall-of-fame','See Hall of Fame',true))+card('<h3>CHALLENGES</h3><p>Earn legitimate milestones through consistency.</p>'+btn('/challenges','Explore challenges',true))+'</div>';
 return '<section class="hero-crop arena-sparring-hero"><img src="'+A+'arena-combatants-approved.png" alt="Jack and Jill facing each other in friendly competitive sparring, beside the RAVN Arena flag"></section><div class="center arena-leaderboard-action">'+btn('/arena/leaderboard','View leaderboard →')+'</div>'+section('YOUR ARENA COLLECTION',card('<h3>BADGES · TROPHIES</h3><p>Discover your five elemental badges and celebrate every milestone.</p>'+btn('/arena/achievements','Open your collection')))+section('COMPETE · PROGRESS · EARN',featureCards)+section('MONTHLY LEADERBOARD',s.joined?'<div class="grid cols2">'+panel+scoring+'</div>':card('<div class="eyebrow">MEMBERS ONLY</div><h3>The leaderboard is waiting for you.</h3><p>Sign up for a free member profile to enter the Arena and see the rankings.</p>'+btn('/signup','Join RAVN South')) )+section('BUILD YOUR LEGACY',legacy);
}
function arenaLeaderboard(){return pageHero('ARENA LEADERBOARD','MEMBERS ONLY · CONSISTENCY WINS.','Every genuine step has value. Compete through accountability and achievements.')+section('CURRENT STANDINGS',s.joined?card('<div class="eyebrow">DEMONSTRATION RANKINGS · '+month()+'</div><div class="tabs"><button class="tab active" data-action="leader-tab" data-period="month">This month</button><button class="tab" data-action="leader-tab" data-period="all">All time</button></div><div class="tablewrap"><table><thead><tr><th>Rank</th><th>Member</th><th>Points</th><th>Badges</th><th>Trophies</th></tr></thead><tbody id="leaderrows">'+rankRows()+'</tbody></table></div><p class="mini">Sample competitors are fictitious. Your demo points are only stored on this device.</p>'):card('<h3>MEMBERS-ONLY STANDINGS</h3><p>Create a free demo profile to enter the Arena.</p>'+btn('/signup','Join free')))+section('THE BIGGER PICTURE',card('<h3>LONG-TERM CONSISTENCY</h3><p>Monthly standings begin again. The Hall of Fame is where members build their legacy.</p>'+btn('/hall-of-fame','Hall of Fame',true)))}
function hall(){const honours=[['','CONSISTENCY','Recognised for sustained effort'],['','ACHIEVEMENT','Recognised for major milestones'],['','COMMUNITY','Recognised for encouraging others']];const inner='<div class="grid cols3">'+honours.map(h=>card('<h3>'+h[1]+'</h3><p>'+h[2]+'</p><span class="tag">Future member honours</span>')).join('')+'</div><div class="line"></div><p>No genuine Hall of Fame winners have been recorded in this prototype. Members will be featured once verifiable competition history exists.</p>';return pageHero('HALL OF FAME','CONSISTENCY BUILDS A LEGACY.','The Arena starts afresh every month. The Hall of Fame celebrates long-term achievement.')+section('FOUNDING HONOURS',s.joined?inner:card('<h3>Members-only recognition</h3><p>Enter the member area to view the Hall of Fame.</p>'+btn('/signup','Join RAVN South')),btn('/arena','Back to Arena',true))}

function challenges(){
 const items=[['Check in today','Reflect on your effort','checkin',5],['Complete planned training','Follow through with training','training',10],['Monthly consistency challenge','Show up this month','challenge',20]];
 const content='<div class="grid cols3">'+items.map(([t,d,key,v])=>card('<h3>'+t+'</h3><p>'+d+'</p><button class="btn-outline" data-action="log" data-key="'+key+'" data-points="'+v+'" data-label="'+t+'" '+((key==='challenge'?s.logs.some(x=>x.key==='challenge'&&x.ref===month()):logged(key))?'disabled':'')+'>Record achievement · +'+v+' pts</button>')).join('')+'</div><p class="mini">Production scores will require verification.</p>';
 return pageHero('CHALLENGES','SHOW UP. KEEP GOING.','Recognise consistency, not strength or appearance.')+section('YOUR CHALLENGES',content)
}
function achievements(){return arenaAchievements()}

function dashboard(){return pageHero('MEMBER DASHBOARD','YOUR JOURNEY. YOUR PROGRESS.','Training, nutrition, mentality and community — everything in one personal space.')+section('YOUR SPACE',`${memberNotice()}<div class="grid cols3">${progressCard()}${card(`<div class="eyebrow">TODAY’S ACTIONS</div><h3>Build your consistency</h3>${[['training','Training',10],['nutrition','Nutrition',10],['checkin','Accountability',5]].map(([key,l,v])=>`<div class="list-row"><span>${logged(key)?'✓':'○'} ${l}</span><button class="btn-soft small" data-action="log" data-key="${key}" data-points="${v}" data-label="${l} completed" ${logged(key)?'disabled':''}>${logged(key)?'Done':'+'+v+' pts'}</button></div>`).join('')}`)}${card(`<div class="eyebrow">YOUR MEMBERSHIP</div><h3>${esc(s.tier)} member</h3><p>Current programme: ${esc(s.program)}</p>${btn('/membership','Explore membership',true)}<div class="line"></div>${btn('/profile','Edit your profile',true)}`)}</div>`)+section('YOUR PERSONAL TOOLS',`<div class="grid cols4">${[['','Accountability','/accountability'],['✓','My Goals','/goals'],['','My Programme','/fitness-programmes'],['','Social Profile','/profile'],['','Messages','/messages'],['','RAVN Arena','/arena'],['','Coach Jill','/coach/jill'],['','Coach Jack','/coach/jack']].map(([sym,t,p])=>card(`<h3>${t}</h3>${btn(p,'Open',true)}`)).join('')}</div>`) }
function accountability(){return pageHero('ACCOUNTABILITY','SMALL ACTIONS. REAL CONSISTENCY.','Measure the effort you put in, not just the outcome.')+section('YOUR DAILY CHECK-IN',`<div class="grid cols2">${card(`<div class="eyebrow">TODAY’S REFLECTION</div><h3>What did you do for yourself today?</h3><label class="field"><span>Your effort, however small</span><textarea id="checkin" rows="5" placeholder="Even if something didn’t go to plan, what did you try?">${esc(s.checkinText)}</textarea></label><button class="btn" data-action="checkin" ${logged('checkin')?'disabled':''}>${logged('checkin')?'✓ Checked in today':'Save check-in · +5 points'}</button>`)}${card(`<h3>CONSISTENCY COUNTS</h3><p>A missed attempt can still teach something. Record genuine effort, reflect and plan your next step.</p><div class="stats" style="grid-template-columns:1fr 1fr"><div class="stat"><strong>${s.logs.filter(l=>l.key==='checkin').length}</strong><span>Check-ins logged</span></div><div class="stat"><strong>${monthly()}</strong><span>This month's points</span></div></div>${btn('/arena','View the Arena',true)}`)}</div>`) }
function membership(){let tiers=[['Free','£0','Free Beginner training and nutrition plans, your profile, Vault and starter progress tracking.'],['Subscription','£9.99','Intermediate and Advanced training and nutrition plans, plus progression tools. Advanced training retains its readiness requirement.'],['Platinum','Future tier','Additional advanced support for members who have earned the relevant progression milestones.']];return pageHero('MEMBERSHIP','YOU ARE INVESTING IN YOURSELF.','Explore the opportunities available at every stage. Advanced programmes are earned through effort, not simply bought.')+section('FIND YOUR PLACE',`<div class="grid cols3 tiers">${tiers.map(([t,price,d])=>card(`<div class="eyebrow">RAVN SOUTH</div><h3>${t.toUpperCase()}</h3><div class="price">${price}${price!=='Future tier'?'<small> / month</small>':''}</div><div class="line"></div><div class="grow"><p>${d}</p>${(t==='Free'?['Beginner training plans','Beginner nutrition plans','Community profile and Vault']:t==='Subscription'?['Intermediate training and nutrition','Advanced training and nutrition','Advanced training readiness still applies']:['Long-term advancement','Eligible advanced content','Milestone-based access']).map(x=>`<div class="checkline">✓ ${x}</div>`).join('')}</div><button class="btn" data-action="tier" data-tier="${t}" ${s.tier===t?'disabled':''}>${s.tier===t?'CURRENT TIER':t==='Platinum'?'VIEW ELIGIBILITY':'TRY '+t.toUpperCase()+' DEMO'}</button><p class="mini">${t==='Free'?'No payment required.':t==='Subscription'?'Prototype only — no payment processed.':'Not purchasable in this prototype.'}</p>`)).join('')}</div>`)+section('PROGRESSION CANNOT BE BOUGHT',card(`<h3>EARN YOUR NEXT STAGE</h3><p>Points, accountability, consistency and real milestones unlock progress. Subscription does not let someone skip the work.</p>${btn('/arena','Visit RAVN Arena',true)}`)) }
function login(){return pageHero('MEMBER ACCESS','WELCOME BACK.','Explore the connected member experience in demo mode.')+section('ENTER THE DEMO',`<div style="max-width:550px;margin:auto">${card(`<div class="notice">Demo access only: this is not a secure account login and should not be used with real passwords.</div><label class="field"><span>Your display name</span><input id="demoName" maxlength="45" value="${esc(s.name==='RAVN Member'?'':s.name)}" placeholder="e.g. Alex R."></label><button class="btn" data-action="demo-login">Enter member dashboard →</button><div class="line"></div><p>New here? <a href="#/signup" style="color:var(--green)">Create a demo profile</a></p>`)}</div>`) }
function signup(){return pageHero('START YOUR JOURNEY','EVERY STEP SHOULD FEEL LIKE AN ACHIEVEMENT.','Create a local demo profile, choose your goals and explore RAVN South.')+section('YOUR FIRST STEP',`<div style="max-width:600px;margin:auto">${card(`<label class="field"><span>Your display name</span><input id="signupName" maxlength="45" placeholder="How should members see your name?"></label><label class="field"><span>Your focus</span><select id="signupGoal"><option>Build consistency</option><option>Build strength</option><option>Improve nutrition</option><option>Build confidence</option><option>Support my general wellbeing</option></select></label><button class="btn" data-action="signup">Create demo profile</button><p class="mini">This local demo doesn't collect a password or register you on a live service.</p>`)}</div>`) }
function profile(){return pageHero('YOUR PROFILE','YOUR STORY. YOUR CHOICE.','Show the progress you choose to share.')+section('PERSONAL PROFILE',`<div class="grid cols2">${card(`<div class="profilehero">${avatar(s.name)}<div><h3>${esc(s.name)}</h3><span class="pill">${esc(s.tier)} member</span><p>${s.points} points · Level ${level()}</p></div></div><div class="line"></div><label class="field"><span>Display name</span><input id="profileName" maxlength="45" value="${esc(s.name)}"></label><label class="field"><span>Profile visibility</span><select id="visibility"><option value="members" ${s.visibility==='members'?'selected':''}>Members can see my profile</option><option value="private" ${s.visibility==='private'?'selected':''}>Private profile (demo preference)</option></select></label><button class="btn" data-action="save-profile">Save profile</button>`)}${card(`<h3>YOUR PROGRESS</h3><div class="stat"><strong>${s.points}</strong><span>Points earned</span></div><div class="line"></div><p>Current training path: ${esc(s.program)}</p>${btn('/arena/achievements','Badges & trophies',true)}<div class="line"></div>${btn('/settings','Account settings',true)}<div class="profile-share-actions"><button class="btn-outline" data-share-profile ${s.visibility==='private'?'disabled':''}>Share profile</button><p class="mini">${s.visibility==='private'?'Your profile is private. Change visibility to share.':'Shares your display name and a snapshot of your award totals.'}</p></div>${profileAwardBanner(profileAwardCounts())}`,'profile-progress-card')}</div>`) }
function groups(){let gs=['Strength & Training','Nutrition Together','Mindset & Motivation','New Members','Walkers & Runners','The Accountability Circle'];return pageHero('COMMUNITY GROUPS','FIND YOUR PEOPLE.','Connect with members who share your interests and goals.')+section('DISCOVER GROUPS',`<div class="grid cols3">${gs.map((g,i)=>card(`<h3>${g}</h3><p>Share ideas, encouragement and small victories with like-minded people.</p><button class="btn-outline" data-action="group" data-name="${esc(g)}">${s.groups.includes(g)?'✓ Joined':'Join group'}</button>`)).join('')}</div><p class="mini" style="margin-top:20px">Group memberships are saved locally. Member-to-member rooms require a shared backend.</p>`) }
function messages(){return pageHero('MESSAGING','CONNECTION STARTS WITH A CONVERSATION.','Preview how your member messaging space will look.')+section('YOUR MESSAGES',`<div class="grid cols2">${card(`<h3>DEMO CONVERSATION</h3><div id="messageChat" class="chat">${[{from:'Jack',text:'Welcome to your RAVN South inbox. Real member messaging will become available when secure accounts are connected.'},...s.messages].map(m=>`<div class="bubble ${m.from==='You'?'me':''}">${esc(m.text)}</div>`).join('')}</div><div class="chatinput"><input id="messageText" placeholder="Write a demo message..." maxlength="400"><button class="btn" data-action="message">Send</button></div>`)}${card(`<h3>PRIVACY FIRST</h3><p>In the finished Vault, members will control who can contact them and what profile information is visible.</p><p class="mini">This messaging panel is local-only: no real message will be sent to another person.</p>${btn('/settings','Privacy settings',true)}`)}</div>`) }
function coaches(){return pageHero('MEET YOUR COACHES','TWO SPECIALITIES. ONE JOURNEY.','Jack supports training and nutrition questions. Jill supports mentality and the five-step program to mentality.')+section('COACH JACK & COACH JILL',`<div class="approved-coach-grid">${['jack','jill'].map((who,i)=>`<a class="approved-coach-card approved-coach-${who}" href="#/coach/${who}" aria-label="Talk to Coach ${who==='jack'?'Jack — training and nutrition':'Jill — mentality and mindset'}"><img src="${A}${who==='jack'?'coaches-snow-approved.png':'coaches-sunrise-approved.png'}" alt="" aria-hidden="true"><span class="visually-hidden">COACH ${who.toUpperCase()} · ${i===0?'Training & nutrition':'Mentality & mindset'} · Talk to ${who==='jack'?'Jack':'Jill'}</span></a>`).join('')}</div>`)}
const coachOpeners={jack:'Hi, I’m Coach Jack. Want help with training consistency, technique or planning a session?',jill:'Hi, I’m Coach Jill. What’s motivating you right now, and what feels hardest about staying consistent?'};
function coachPage(who){if(!['jack','jill'].includes(who))return notFound();let isJ=who==='jill';let prompts=isJ?['I struggle with motivation','I feel disappointed after a setback','How do the five-step program to mentality work?']:['Help me start training','How can I progress safely?','How do I stay consistent?'];return pageHero(`COACH ${who.toUpperCase()}`,isJ?'MENTALITY · REFLECTION · FIVE STEPS':'TRAINING · TECHNIQUE · PROGRESSION',isJ?'Explore your goals, mindset and reasons for change.':'Work through practical training questions and build your confidence.')+section('YOUR COACHING SPACE',`<div class="grid cols2">${card(`<div class="coach-head">${isJ?`<div class="approved-coach-card approved-coach-jill jill-coaching-background"><img src="${A}coaches-sunrise-approved.png" alt="Coach Jill with the agreed sunrise, mountains and lake background"></div>`:`<img class="coach-portrait jack-snow-portrait" src="${A}coach-jack-snow-portrait.png" alt="Coach Jack in his RAVN South hoodie against snowy mountain peaks">`}<div><h3>COACH ${who.toUpperCase()}</h3><p class="mini">Guided demo · not a live AI coach</p></div></div><div class="line"></div><div class="chat" id="coachChat"><div class="bubble">${coachOpeners[who]}</div></div><div class="chatinput"><input id="coachInput" maxlength="350" placeholder="Ask a question..."><button class="btn" data-action="coach" data-who="${who}">Send</button></div><div class="tabs" style="margin-top:15px">${prompts.map(t=>`<button class="btn-soft small" data-action="coach-quick" data-who="${who}" data-question="${esc(t)}">${t}</button>`).join('')}</div>`)}${card(`<h3>YOUR COACH'S FOCUS</h3>${isJ?`<p>Jill works through the five-step program to mentality with open questions, helping you understand the motivation behind your actions.</p>${pillars.map(p=>`<div class="list-row">${p[0]} <span class="muted"></span></div>`).join('')}`:`<p>Jack focuses on practical training choices and reinforcing safe, sustainable routines.</p>${programData.map(p=>`<div class="list-row">${p.title} <a href="#/training/${p.slug}">View</a></div>`).join('')}`}<p class="mini">Answers here are a scripted preview. Genuine AI functionality needs a connected, monitored service and approved coaching material.</p>`)} </div>`)}
function coachReply(who,q){let t=q.toLowerCase();if(who==='jill'){if(/motivat|why|start/.test(t))return 'What matters most to you about making this change? Is it how you feel, what you enjoy, your health, or something else? There is no one right reason.';if(/setback|fail|disappoint|miss/.test(t))return 'What did you still manage to try? That effort counts. What could make the next attempt a little easier without putting pressure on the rest of your life?';if(/pillar|five.step|mentality program/.test(t))return 'Our five steps are Motivation, Determination, Gratification, Sustainability and Maintenance. Which one feels most relevant to you today?';return 'That sounds important. What would a small, achievable step look like for you — something you could feel good about trying?'}if(/safe|progress|strong|weight/.test(t))return 'Progress gradually, prioritise movement control and leave room for recovery. What movement are you working on and how confident are you with its form?';if(/consistent|start|plan/.test(t))return 'Start with sessions you can genuinely fit into your week. Choose a clear, repeatable plan, then build from there. Would you prefer a full-body foundation or a technique-focused start?';return 'I can help you think through a routine or a technique question. What exercise or training goal would you like to focus on?'}
function settings(){return pageHero('SETTINGS','YOUR ACCOUNT. YOUR CONTROL.','Manage the preferences in your local development profile.')+section('YOUR PREFERENCES',`<div class="grid cols2">${card(`<h3>PRIVACY & NOTIFICATIONS</h3><label class="checkline"><input id="noticecheck" type="checkbox" ${s.notices?'checked':''}>Show progress notifications</label><label class="field"><span>Profile visibility</span><select id="settingsVisibility"><option value="members" ${s.visibility==='members'?'selected':''}>Members</option><option value="private" ${s.visibility==='private'?'selected':''}>Private</option></select></label><button class="btn" data-action="save-settings">Save preferences</button><p class="mini">Actual privacy enforcement requires authenticated server-side controls.</p>`)}${card(`<h3>DEMO DATA</h3><p>Your prototype progress, posts and preferences are stored in this browser. You can reset them at any time.</p><button class="btn-soft" data-action="reset">Reset my demo data</button><div class="line"></div><a class="btn-outline" href="#/privacy">Read privacy information</a>`)} </div>`) }
function results(){return pageHero('RESULTS & PROGRESS','YOUR PROGRESS HAS A STORY.','Recognise the actions that made a difference.')+section('YOUR JOURNEY SO FAR',`<div class="grid cols3">${card(`<div class="stat"><strong>${s.points}</strong><span>Points earned</span></div>`)}${card(`<div class="stat"><strong>${s.logs.length}</strong><span>Actions recorded</span></div>`)}${card(`<div class="stat"><strong>${level()}</strong><span>Current level</span></div>`)}</div><div class="line"></div>${card(`<h3>RECENT PROGRESS</h3>${s.logs.length?s.logs.slice(0,8).map(x=>`<div class="list-row"><span>${esc(x.label)}</span><span>+${x.points}</span></div>`).join(''):'Your first recorded action will appear here.'}`)}`,btn('/accountability','Add today’s progress')) }
function about(){return pageHero('OUR STORY','MORE THAN NUMBERS.','RAVN South is built around achievement, belonging, and sustainable personal growth.')+section('WHY WE BUILT THIS',`<div class="grid cols2">${card(`<h3>DO IT. PROVE IT.</h3><p>You don’t have to be perfect to make progress. Turning up, trying again and making one better decision all deserve recognition.</p><p>The five-step program to mentality is the foundation of training, nutrition and mentality across the community.</p>`)}${card(`<img class="banner-img" src="${A}jack-jill.webp" alt="Jack and Jill in the RAVN South brand hero"><h3 style="margin-top:16px">A JOURNEY YOU CAN BELONG TO</h3><p>A home for people improving their health, confidence, strength and habits at their own pace.</p>`)} </div>`)+section('MEET THE TEAM',card(`<h3>JACK & JILL</h3><p>Our two coaching characters support different parts of the same journey.</p>${btn('/coaches','Meet the coaches')}`)) }
function contact(){return pageHero('CONTACT','WE’RE HERE TO LISTEN.','Questions, feedback or ideas for RAVN South?')+section('SEND AN ENQUIRY',`<div style="max-width:720px">${card(`<label class="field"><span>Your name</span><input id="contactName" maxlength="80" placeholder="Your name"></label><label class="field"><span>Email</span><input id="contactEmail" type="email" placeholder="you@example.com"></label><label class="field"><span>Message</span><textarea id="contactMsg" rows="5" maxlength="2000" placeholder="How can we help?"></textarea></label><button class="btn" data-action="contact">Prepare enquiry</button><p class="mini">Until a contact service is connected, the demo will prepare an email in your email app rather than submit it to a server.</p>`)}</div>`) }
const faqData=[['Do I need to pay to use the community?','The planned Vault community experience is free for signed-up members. Paid tiers add enhanced member features.'],['Can I buy the highest training level?','No. Advanced programme access should be earned through effort, consistency and appropriate milestones, not simply purchased.'],['How does the Arena work?','Members earn legitimate points through training, nutrition, check-ins and challenges. The monthly leaderboard ranks overall achievement.'],['Are there prizes for first place?','No separate reward is planned. Recognition on the leaderboard is the reward.'],['Is this version live?','This is a functional interactive prototype. Shared accounts, payments, AI and social data are not yet connected.']];
function faq(){return pageHero('FREQUENTLY ASKED QUESTIONS','CLEAR ANSWERS.','Learn how the RAVN South experience works.')+section('YOUR QUESTIONS',`<div class="list">${faqData.map(([q,a])=>`<details class="card" style="padding:17px 22px"><summary style="cursor:pointer;font-weight:700">${q}</summary><p style="margin-top:16px">${a}</p></details>`).join('')}</div>`) }
function privacy(){return pageHero('PRIVACY','YOUR JOURNEY BELONGS TO YOU.','Understand how this prototype handles your information.')+section('PROTOTYPE PRIVACY',card(`<h3>Local demonstration only</h3><p>The demo saves your display name, actions and posts to localStorage on your own device so you can test navigation and progress. It has no backend member database or live member feed. The Share profile option creates a link containing your display name and a snapshot of your award totals; recipients can retain or forward it. Changing your local visibility does not revoke an existing share link. Avoid entering sensitive health data. You can clear the demo through Settings.</p><p>Real authentication, privacy controls, moderation, data retention and a full legal privacy notice will be required before launch.</p>${btn('/settings','Manage local data',true)}`)) }
function terms(){return pageHero('TERMS & CONDITIONS','PROTOTYPE INFORMATION.','Information about this demonstration website.')+section('DEVELOPMENT PREVIEW',card(`<h3>Not yet a live membership platform</h3><p>All plans, social interactions, points and achievements in this version are demonstrations. No paid services or secure user accounts are active. Training and nutrition information is illustrative and not a substitute for tailored professional guidance.</p><p>Before public release, RAVN South will need approved Terms, Privacy Policy, safeguarding and community rules, and secure services.</p><p>Read the <a href="#/disclaimer">full site disclaimer</a> for training, nutrition, wellbeing, digital coaches, sharing and membership limitations. It does not remove your statutory rights.</p>`)) }
function notFound(){return pageHero('PAGE NOT FOUND','LET’S FIND YOUR WAY BACK.','The page you asked for is not part of this build.')+section('KEEP EXPLORING',card(`<h3>YOUR JOURNEY CONTINUES</h3>${btn('/','Back to home')}`))}

function stories(){return pageHero('MEMBER STORIES','PROGRESS DESERVES TO BE SEEN.','Share a short update about the steps that matter to you.')+section('YOUR STORIES',`${memberNotice()}<div class="grid cols2">${card(`<h3>SHARE A STORY</h3><label class="field"><span>Today’s story</span><textarea id="storyText" maxlength="300" rows="4" placeholder="A small win, a setback you learned from, or something you’re proud of..."></textarea></label><button class="btn" data-action="story">Add story</button><p class="mini">Visible only on this device during the demo; not posted to other members.</p>`)}${card(`<h3>STORYBOARD</h3>${s.stories.length?s.stories.slice(0,12).map(x=>`<div class="list-row"><div><span class="eyebrow">${esc(x.name)}</span><p>${esc(x.text)}</p><small>${new Date(x.at).toLocaleDateString('en-GB')}</small></div></div>`).join(''):'<p>Your first story will appear here.</p>'}`)}</div>`)}
const demoCommunity=['Hannah P.','Mark D.','Emma L.','James K.'];
function gifting(){return pageHero('GIFTING & RECOGNITION','ENCOURAGEMENT IS A STRENGTH.','Show support for effort, growth, kindness and consistency.')+section('SEND A GESTURE',`${memberNotice()}<div class="grid cols2">${card(`<h3>RECOGNISE A MEMBER</h3><label class="field"><span>Choose a demonstration member</span><select id="giftTo">${demoCommunity.map(n=>`<option>${n}</option>`).join('')}</select></label><label class="field"><span>Choose a gift</span><select id="giftType"><option>Consistency Star</option><option>Well Done</option><option>Great Encouragement</option><option>Keep Going</option></select></label><label class="field"><span>Your message</span><input id="giftMessage" maxlength="100" placeholder="You inspired me to keep showing up"></label><button class="btn" data-action="gift">Send demo gesture</button><p class="mini">This is a personal local demonstration. Nothing is delivered to another user.</p>`)}${card(`<h3>YOUR SENT GESTURES</h3>${s.gifts.length?s.gifts.map(x=>`<div class="list-row"><span><strong> ${esc(x.type)}</strong> for ${esc(x.to)}<br><small>${esc(x.message)}</small></span><span class="mini">Demo</span></div>`).join(''):'<p>Celebrate someone’s progress with a first gesture.</p>'}`)}</div>`)}
function buddies(){return pageHero('TRAINING BUDDIES','YOU DO NOT HAVE TO DO IT ALONE.','Explore a future matching space based on shared interests, not appearance.')+section('FIND YOUR TRIBE',`${memberNotice()}<div class="grid cols3">${[['Strength training','Hannah P.','Build technique together'],['Everyday walking','Mark D.','Consistency matters more than speed'],['Nutrition accountability','Emma L.','Share meal-prep motivation']].map(([interest,name,detail])=>card(`<div class="eyebrow">${interest}</div><h3>${name}</h3><p>${detail}</p><button class="btn-outline" data-action="buddy" data-name="${name}">${s.buddies.includes(name)?'✓ Interest saved':'Save interest'}</button>`)).join('')}</div><p class="mini">People shown are illustrative. This feature does not connect or disclose anyone’s location.</p>`)}
function media(){return pageHero('MEDIA LIBRARY','STORIES. LESSONS. MOMENTUM.','A home for future RAVN South training, nutrition and mentality videos.')+section('EXPLORE THE COLLECTION',`<div class="grid cols3">${[['training','TRAINING TECHNIQUES','/fitness-programmes','Build confident, controlled movement.'],['nutrition','NUTRITION GUIDES','/nutrition','Learn sustainable meal routines.'],['mentality','THE FIVE-STEP PROGRAM','/mentality','Understand the purpose behind each step.']].map(([img,title,url,desc])=>card(`<img class="banner-img" src="${A+(img==='nutrition'?'nutrition-hd':img)}.webp" alt="${title}"><h3 style="margin-top:18px">${title}</h3><p>${desc}</p>${btn(url,'Explore related content',true)}`)).join('')}</div><p class="mini" style="margin-top:20px">Video uploads and streaming will be connected when you provide the approved media.</p>`)}
function goals(){return pageHero('YOUR GOALS','SMALL STEPS. REAL DIRECTION.','Define achievable steps without sacrificing the balance of home, family, work and health.')+section('YOUR PERSONAL GOAL LIST',`${memberNotice()}<div class="grid cols2">${card(`<label class="field"><span>One achievable next step</span><input id="goalText" maxlength="150" placeholder="e.g. Get to the gym twice this week"></label><button class="btn" data-action="add-goal">Add a goal</button>`)}${card(`<h3>YOUR GOALS & REFLECTIONS</h3>${s.goals.length?s.goals.map((g,i)=>`<div class="list-row"><span>${esc(g)}</span><button class="btn-soft small" data-action="remove-goal" data-index="${i}" aria-label="Remove goal">Remove</button></div>`).join(''):'<p>Choose something you can realistically work towards.</p>'}`)}</div>`)}

function render(){if(path()==='/achievements')history.replaceState(history.state,'','#/arena/achievements');const p=path();let content=p==='/'?home():p.startsWith('/fitness-programmes')?fitnessRoute(p):p==='/training'?training():p.startsWith('/training/')?trainingDetail(p.split('/')[2]):p==='/nutrition'?nutrition():p==='/nutrition/rotation'?rotation():p==='/nutrition/snacks'?nutritionSnacks():p==='/nutrition/shopping'?nutritionShopping():p.startsWith('/nutrition/plan/')?nutritionDetail(p.split('/')[3],p.split('/')[4],p.split('/')[5]):p==='/mentality'?mentality():p.startsWith('/mentality/')?pillarDetail(p.split('/')[2]):p==='/vault'?vault():p==='/vault/feed'?feed():p==='/vault/stories'?stories():p==='/vault/gifting'?gifting():p==='/vault/buddies'?buddies():p==='/arena'?arena():p==='/arena/achievements'?achievements():p==='/arena/leaderboard'?arenaLeaderboard():p==='/hall-of-fame'?hall():p==='/challenges'?challenges():p==='/achievements'?achievements():p==='/dashboard'?dashboard():p==='/accountability'?accountability():p==='/membership'?membership():p==='/login'?login():p==='/signup'?signup():p==='/profile'?profile():p.startsWith('/profile/shared/')?sharedProfile(p.slice('/profile/shared/'.length)):p==='/groups'?groups():p==='/messages'?messages():p==='/coaches'?coaches():p.startsWith('/coach/')?coachPage(p.split('/')[2]):p==='/settings'?settings():p==='/results'?results():p==='/goals'?goals():p==='/media'?media():p==='/about'?about():p==='/contact'?contact():p==='/faq'?faq():p==='/privacy'?privacy():p==='/terms'?terms():p==='/disclaimer'?siteDisclaimer():notFound();$('#app').innerHTML=header()+`<main class="page">${p!=='/'?'<div class="wrap page-return"><button type="button" class="btn-outline" data-site-back>Back</button></div>':''}<div class="notice wrap">TESTING SITE · Demo changes stay on this device. Accounts, payments and AI are demonstrations.</div>${disclaimerNotice(p)}${content}</main>`+footer();document.title=p==='/'?'RAVN South | Training, Nutrition & Mentality':'RAVN South · '+(p.startsWith('/profile/shared/')?'Member profile':p==='/'?'Home':p.split('/').filter(Boolean).map(x=>x.replace(/-/g,' ')).join(' / '));}
// Route changes and scroll restoration are handled by navigation.js.
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let action=b.dataset.action;if(action.startsWith('f-')&&fAction(b)){e.preventDefault();return}let v=id=>document.getElementById(id)?.value||'';
if(action==='story'){let t=v('storyText').trim();if(!s.joined)return navto('/signup');if(t.length<3)return toast('Write a little more to share.');s.stories.unshift({name:s.name,text:t,at:new Date().toISOString()});save();render();toast('Story saved to this device');return}
if(action==='gift'){if(!s.joined)return navto('/signup');s.gifts.unshift({to:v('giftTo'),type:v('giftType'),message:v('giftMessage')});save();render();toast('Demo gesture saved');return}
if(action==='buddy'){if(!s.joined)return navto('/signup');let n=b.dataset.name;s.buddies=s.buddies.includes(n)?s.buddies.filter(x=>x!==n):[...s.buddies,n];save();render();toast('Matching preference saved locally');return}
if(action==='add-goal'){if(!s.joined)return navto('/signup');let t=v('goalText').trim();if(t.length<3)return toast('Add a short goal.');s.goals.unshift(t);save();render();toast('Goal saved');return}
if(action==='remove-goal'){s.goals.splice(Number(b.dataset.index),1);save();render();toast('Goal removed');return}
if(action==='menu'){$('#mainnav').classList.toggle('open');return}
if(action==='log'){logAction(b.dataset.key,Number(b.dataset.points),b.dataset.label,b.dataset.key==='challenge'?'month':'day');return}
if(action==='choose-program'){const plan=programData.find(x=>x.title===b.dataset.program);if(!plan||!programmeAllowed(legacyTrainingLevel(plan.slug)))return navto('/membership');s.program=b.dataset.program;save();toast('Programme selected');render();return}
if(action==='leader-tab'){document.querySelectorAll('[data-action="leader-tab"]').forEach(el=>el.classList.toggle('active',el===b));$('#leaderrows').innerHTML=rankRows(b.dataset.period);return}
if(action==='post'){let text=v('posttext').trim();if(!s.joined)return navto('/login');if(text.length<3)return toast('Write a little more before posting.');s.posts.unshift({id:'p'+Date.now(),name:s.name,text,likes:0,age:'Just now'});save();toast('Post added to your local demo feed');render();return}
if(action==='like'){let id=b.dataset.id;s.likes=s.likes.includes(id)?s.likes.filter(x=>x!==id):[...s.likes,id];save();render();return}
if(action==='tier'){if(!s.joined)return navto('/login');if(b.dataset.tier==='Platinum')return toast('Platinum requires earned eligibility. It cannot be bought here.');s.tier=b.dataset.tier;save();toast('Demo tier updated — no payment taken');render();return}
if(action==='demo-login'||action==='signup'){let name=(action==='signup'?v('signupName'):v('demoName')).trim();if(name.length<2)return toast('Please enter a display name (at least 2 characters).');s.name=name;s.joined=true;if(action==='signup')s.goals=[v('signupGoal')];save();toast('Welcome to RAVN South');navto('/dashboard');return}
if(action==='save-profile'){let name=v('profileName').trim();if(name.length<2)return toast('Please enter a valid display name.');s.name=name;s.visibility=v('visibility');save();toast('Profile preferences saved');render();return}
if(action==='group'){let g=b.dataset.name;s.groups=s.groups.includes(g)?s.groups.filter(x=>x!==g):[...s.groups,g];save();toast(s.groups.includes(g)?'Joined your demo group':'Left demo group');render();return}
if(action==='message'){let msg=v('messageText').trim();if(!msg)return toast('Write a message.');s.messages.push({from:'You',text:msg});save();render();return}
if(action==='coach'||action==='coach-quick'){let who=b.dataset.who,q=action==='coach-quick'?b.dataset.question:v('coachInput').trim();if(!q)return toast('Write a question.');let box=$('#coachChat');if(box){let mine=document.createElement('div');mine.className='bubble me';mine.textContent=q;box.append(mine);let reply=document.createElement('div');reply.className='bubble';reply.textContent=coachReply(who,q);box.append(reply);box.scrollTop=box.scrollHeight;let inp=$('#coachInput');if(inp)inp.value=''}return}
if(action==='checkin'){let text=v('checkin').trim();if(!text)return toast('Write a short reflection first.');s.checkinText=text;save();logAction('checkin',5,'Accountability check-in');return}
if(action==='reflect'){let text=v('reflect').trim();if(text.length<3)return toast('Write one small step.');s.goals.unshift(b.dataset.pillar+': '+text);save();toast('Reflection saved to your local profile');return}
if(action==='save-settings'){s.notices=$('#noticecheck').checked;s.visibility=v('settingsVisibility');save();toast('Preferences saved');render();return}
if(action==='reset'){if(confirm('Clear your local RAVN South demo profile, posts and progress?')){s={...defaults};save();toast('Demo data reset');navto('/')}return}
if(action==='contact'){let name=v('contactName').trim(),mail=v('contactEmail').trim(),msg=v('contactMsg').trim();if(!name||!/^\S+@\S+\.\S+$/.test(mail)||!msg)return toast('Please add your name, valid email and message.');let subject=encodeURIComponent('RAVN South enquiry from '+name),body=encodeURIComponent(msg+'\n\nFrom: '+name+'\nEmail: '+mail);location.href='mailto:?subject='+subject+'&body='+body;toast('Email draft prepared — add the recipient address.');return}
});
document.addEventListener('input',e=>{if(e.target.dataset.fFilter==='search')fFilterChange(e.target)});
document.addEventListener('change',e=>{
 if(e.target.dataset.fFilter&&e.target.dataset.fFilter!=='search'){fFilterChange(e.target);return}
 if(e.target.matches('.f-exercise-check')){let el=e.target;const plan=fitnessPrograms.find(x=>x.id===el.dataset.program);if(!plan||!programmeAllowed(plan.level)||(plan.level==='Advanced'&&(s.fitnessSessions?.length||0)<8))return;let key=today()+'|'+el.dataset.program,idx=Number(el.dataset.index);s.fitnessExercises=s.fitnessExercises||{};let arr=s.fitnessExercises[key]||[];s.fitnessExercises[key]=el.checked?[...new Set([...arr,idx])]:arr.filter(x=>x!==idx);save();return}
});
document.addEventListener('change',e=>{if(e.target.matches('.mealcheck')){let k=today()+'-'+e.target.dataset.meal;s.nutrition=e.target.checked?[...new Set([...s.nutrition,k])]:s.nutrition.filter(v=>v!==k);save();toast('Meal planner updated')}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='coachInput'){e.preventDefault();$('[data-action="coach"]')?.click()}if(e.key==='Enter'&&e.target.id==='messageText'){e.preventDefault();$('[data-action="message"]')?.click()}});
render();
